# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, V, D_, Y, M, K, A = "Lucas", "Vicente", "Daniel", "Gaby", "Doña Mercedes", "Kevin", "Amparo"
D = [
("#", "Escena 1 · 17:40 (lunes) · Llegadas del aeropuerto de Miami y autopista", "장면 1 · 월요일 오후 5시 40분 · 마이애미 공항 도착장, 그리고 고속도로"),
(None, "Lunes 21 de septiembre. Las puertas automáticas se abren y entra una bocanada de aire caliente. Entre turistas en pantalón corto aparece Vicente Albalat, con americana gris, una maleta antigua y una caja de cartón atada con cuerda bajo el brazo.", "9월 21일 월요일. 자동문이 열리자 뜨거운 바람이 확 들어온다. 반바지 차림의 관광객들 사이로 회색 재킷에 낡은 여행 가방을 끌고, 끈으로 묶은 종이 상자를 옆구리에 낀 비센테 알발라트가 나타난다."),
(V, "¡Lucas! Qué calor, por Dios. Es como meterse en el horno tres.", "루카스! 세상에, 이 더위 좀 봐. 3호기 안에 들어간 것 같네."),
(L, "Bienvenido a Miami, Vicente. Quítese... quítate la americana, que aquí no la lleva nadie.", "마이애미에 오신 걸 환영해요, 비센테. 재킷 벗으세… 벗어요. 여기선 아무도 안 입어요."),
(V, "Me la quito en el coche. Mi padre decía que a un país nuevo se entra con americana.", "차에서 벗을게. 우리 아버지는 새 나라에는 재킷을 입고 들어가야 한다고 하셨어."),
(L, "¿Qué tal el vuelo?", "비행은 어땠어요?"),
(V, "Largo. Antes los aviones tenían ceniceros y la gente charlaba en el pasillo. Ahora te dan una pantalla y nadie habla con nadie.", "길었지. 예전엔 비행기에 재떨이가 있었고 사람들이 통로에서 수다를 떨었어. 요즘은 화면 하나 주고 아무도 서로 말을 안 해."),
(L, "¿Y la inmigración? ¿Mucha cola?", "입국 심사는요? 줄이 길었어요?"),
(V, "Una hora. El agente me preguntó a qué venía. Le dije «a firmar» y me miró como si fuera un espía.", "한 시간. 심사관이 뭐 하러 왔냐고 묻길래 '서명하러'라고 했더니 날 무슨 스파이 보듯 쳐다보더라."),
(L, "(se ríe) ¿Y qué le contestaste después?", "(웃으며) 그다음엔 뭐라고 했어요?"),
(V, "Que vendo suelos. Entonces sonrió y me dijo que su madre tenía la cocina con azulejos de Valencia. Este país está lleno de gente que ha pisado nuestras baldosas sin saberlo.", "바닥재를 판다고 했지. 그랬더니 웃으면서 자기 어머니 부엌이 발렌시아 타일이라더군. 이 나라엔 우리 타일을 밟고도 모르는 사람들이 가득해."),
(L, "Por eso estamos aquí.", "그래서 우리가 여기 온 거죠."),
(None, "En el coche de alquiler, por la autopista Dolphin. Vicente se quita por fin la americana y la dobla con cuidado sobre las rodillas.", "렌터카를 타고 돌핀 고속도로를 달린다. 비센테가 마침내 재킷을 벗어 무릎 위에 조심스럽게 갠다."),
(V, "Amparo me hizo prometer tres cosas antes de subir al avión.", "암파로가 비행기 타기 전에 세 가지를 약속하게 했어."),
(L, "¿Cuáles?", "뭔데요?"),
(V, "Que no firme nada sin leerlo dos veces. Que te deje hablar a ti de números. Y que me tome la pastilla de la tensión.", "두 번 읽기 전엔 아무것도 서명하지 말 것. 숫자 얘기는 너한테 맡길 것. 그리고 혈압약 챙겨 먹을 것."),
(L, "Las tres son buenas.", "셋 다 좋은 약속이네요."),
(V, "La tercera es la única que pienso cumplir. (pausa) Es broma.", "세 번째만 지킬 생각이야. (잠시 멈춤) 농담이야."),
(L, "Vicente, ¿puedo preguntarte algo personal?", "비센테, 개인적인 거 하나 물어봐도 돼요?"),
(V, "Llevas siete meses preguntándome cosas personales en las sobremesas. Pregunta.", "7개월째 식후 담소 때마다 개인적인 걸 물어보고 있잖아. 물어봐."),
(L, "¿Por qué has venido? Ramón dice que llevabas dieciséis años sin cruzar el Atlántico.", "왜 오셨어요? 라몬 말로는 16년 동안 대서양을 안 건너셨다던데요."),
(V, "Dieciséis años y siete meses. (mira por la ventanilla) En 2009 fui a Guadalajara. Firmé con un hombre muy simpático, comimos tres veces, nos dimos un abrazo... y no volví a ver un euro.", "16년하고 7개월. (창밖을 보며) 2009년에 과달라하라에 갔지. 아주 친절한 남자랑 서명했어. 밥을 세 번 먹고, 포옹도 했고… 그러고는 1유로도 다시 못 봤지."),
(L, "Lo sé. Ramón me lo contó.", "알아요. 라몬이 얘기해 줬어요."),
(V, "Lo que Ramón no te contó es que firmé yo solo, sin leer dos veces. Antes yo firmaba primero y preguntaba después. Era así. Mi padre también era así.", "라몬이 말 안 해 준 건, 내가 혼자서, 두 번 읽지도 않고 서명했다는 거야. 예전에 나는 먼저 서명하고 나중에 물어봤어. 그런 사람이었어. 우리 아버지도 그랬고."),
(L, "¿Y ahora?", "지금은요?"),
(V, "Ahora pregunto primero. Y luego, si me fío, vengo. (pausa) Y he venido porque mi hija me lo pidió en la sobremesa delante de su madre, que es como pedirlo delante de un notario.", "지금은 먼저 물어봐. 그리고 믿을 만하면 오지. (잠시 멈춤) 그리고 내가 온 건 딸이 식후 담소 자리에서 제 엄마 앞에서 부탁했기 때문이야. 그건 공증인 앞에서 부탁하는 거나 마찬가지거든."),
(L, "Amparo dijo que te lo pediría bien.", "암파로가 제대로 부탁드리겠다고 했어요."),
(V, "Me lo pidió muy bien. Me dijo: «Papá, Daniel no quiere tu firma. Quiere verte la cara. Y tú necesitas que te vean la cara fuera de Peñíscola».", "아주 제대로 부탁하더라. 이러더군. '아빠, 다니엘은 아빠 서명을 원하는 게 아니에요. 아빠 얼굴을 보고 싶은 거예요. 그리고 아빠도 페니스콜라 밖에서 얼굴 좀 보여야 해요.'"),
(L, "Eso suena a Amparo.", "암파로다운 말이네요."),
(V, "Suena a su madre. (sonríe) Cuéntame de este Daniel. ¿Cómo es?", "제 엄마다운 말이지. (미소 지으며) 이 다니엘이란 사람 얘기 좀 해 봐. 어떤 사람이야?"),
(L, "Rápido. Habla mitad en español y mitad en inglés. Nos llama «gallegos». Y es el hombre más generoso y más duro negociando que he conocido. Después de usted. De ti.", "빨라요. 반은 스페인어, 반은 영어로 말하고요. 우리를 '갈리시아 사람들'이라고 불러요. 그리고 제가 만난 사람 중에 제일 너그럽고, 협상할 땐 제일 지독해요. 당신 다음으로요. 아니, 너… 다음으로."),
(V, "Todavía me hablas de usted cuando te pones nervioso.", "아직도 긴장하면 나한테 존댓말을 쓰는구나."),
(L, "Solo cuando hablo de negocios contigo. Es como si llevara corbata por dentro.", "당신이랑 사업 얘기할 때만요. 속에 넥타이를 매고 있는 것 같달까요."),
(V, "(se ríe) Corbata por dentro. Esa se la voy a contar a Pepe.", "(웃으며) 속에 넥타이라. 그 말은 페페한테 써먹어야겠다."),
(L, "Mañana comemos en casa de Daniel, con su madre, doña Mercedes. Y a las cinco, la firma en su oficina.", "내일은 다니엘 집에서 어머니 메르세데스 여사님이랑 점심을 먹어요. 그리고 5시에 사무실에서 서명이고요."),
(V, "¿Comida antes de firmar? Eso es muy nuestro.", "서명 전에 식사라고? 그건 완전 우리 방식인데."),
(L, "Muy cubano, dice Daniel. Y muy asturiano, dice su madre.", "다니엘은 완전 쿠바식이래요. 그분 어머니는 완전 아스투리아스식이라고 하고요."),
(V, "Entonces me sentiré como en casa. ¿Habrá café?", "그럼 집처럼 편하겠네. 커피는 있겠지?"),
(L, "En Miami siempre hay café.", "마이애미엔 언제나 커피가 있어요."),

("#", "Escena 2 · 13:00 (martes) · Casa de Daniel, Coral Gables", "장면 2 · 화요일 오후 1시 · 코럴게이블스, 다니엘의 집"),
(None, "Una casa de los años cincuenta, con persianas verdes y un mango en el jardín. En el salón, el suelo es de baldosas hidráulicas de dibujo geométrico, gastadas por el uso. Doña Mercedes, de ochenta y cinco años, vestida de blanco, espera sentada junto a la ventana. Gaby pone la mesa.", "초록색 덧문에 마당엔 망고나무가 있는 1950년대 집. 거실 바닥은 기하학 무늬의 시멘트 타일인데, 오래 밟혀 닳아 있다. 흰 옷을 입은 여든다섯 살의 메르세데스 여사가 창가에 앉아 기다린다. 가비가 식탁을 차린다."),
(D_, "¡Don Vicente! Por fin. Bienvenido a esta casa. Mamá, este es el dueño de los gallegos.", "비센테 사장님! 드디어 오셨네요. 이 집에 오신 걸 환영합니다. 엄마, 이분이 그 갈리시아 사람들의 주인이에요."),
(V, "Encantado, señora. Vicente Albalat. Le he traído esto de Onda.", "반갑습니다, 여사님. 비센테 알발라트입니다. 온다에서 이걸 가져왔습니다."),
(M, "(abre la caja) ¡Ay! Un azulejo... con flores azules. Hacía más de sesenta años que no veía uno así.", "(상자를 열며) 아이고! 타일이네… 파란 꽃무늬. 이런 걸 본 지 60년도 넘었어요."),
(V, "Lo pintaba a mano mi abuelo, antes de que hubiera máquinas. Es de los últimos que quedan en la fábrica.", "기계가 생기기 전에 제 할아버지가 손으로 그리던 겁니다. 공장에 몇 장 안 남은 것 중 하나예요."),
(M, "Mi suegro tenía una ferretería en La Habana, en la calle Muralla. El suelo era de baldosas como esta. Él siempre decía que venían de Castellón.", "우리 시아버지는 아바나 무라야 거리에서 철물점을 하셨어요. 바닥이 이런 타일이었죠. 시아버지는 늘 카스테욘에서 온 거라고 하셨어요."),
(V, "En los años cincuenta, medio Caribe pisaba baldosas de Castellón. A lo mejor alguna era nuestra.", "50년대엔 카리브해의 절반이 카스테욘 타일을 밟았죠. 어쩌면 그중 몇 장은 저희 것이었을지도 모릅니다."),
(M, "A lo mejor. Me gusta pensar que sí.", "어쩌면요. 그랬다고 생각하고 싶네요."),
(Y, "Abuela, cuéntale lo de Llanes.", "할머니, 야네스 얘기 해 드려요."),
(M, "Mi suegro, el abuelo de Daniel, era asturiano, de Llanes. Se fue a Cuba en 1922, con catorce años y una maleta de cartón. Allí abrió la ferretería, se casó y tuvo cuatro hijos. El mayor, Raúl, fue mi marido.", "우리 시아버지, 그러니까 다니엘의 할아버지는 아스투리아스의 야네스 사람이었어요. 1922년에 열네 살 나이로 판지 가방 하나 들고 쿠바로 건너가셨죠. 거기서 철물점을 열고, 결혼해서 자식 넷을 두셨어요. 맏아들 라울이 제 남편이었고요."),
(V, "¿Y usted? ¿Cuándo vino a Miami?", "그럼 여사님은요? 마이애미엔 언제 오셨어요?"),
(M, "En 1961, con veinte años y recién casada. También con una maleta. La ferretería se la habían quitado el año anterior. Es la historia de esta familia: siempre una maleta.", "1961년에, 스무 살에 막 결혼해서요. 저희도 가방 하나 들고요. 철물점은 그 전해에 빼앗겼어요. 이게 우리 집안 이야기예요. 늘 가방 하나."),
(V, "Mi abuelo encendió el primer horno en 1958, con leña. Tres años antes de que usted llegara aquí.", "제 할아버지는 1958년에 장작으로 첫 가마에 불을 붙이셨어요. 여사님이 여기 오시기 3년 전이네요."),
(M, "Fíjese. Mientras su abuelo encendía un horno, mi suegro todavía abría la ferretería cada mañana, como si nada fuera a cambiar.", "그러고 보니 그렇네요. 사장님 할아버지가 가마에 불을 붙이던 때, 우리 시아버지는 아무것도 변하지 않을 것처럼 매일 아침 철물점 문을 여셨어요."),
(V, "Como si nada fuera a cambiar... Eso lo conozco bien.", "아무것도 변하지 않을 것처럼… 그건 저도 잘 압니다."),
(D_, "Mamá, no pongas triste a don Vicente, que viene a firmar.", "엄마, 비센테 사장님 슬프게 하지 마요. 서명하러 오셨는데."),
(M, "No está triste, Danielito. Está pensando. Los hombres que piensan ponen esa cara.", "슬픈 게 아니야, 다니엘리토. 생각하시는 거야. 생각하는 남자들은 저런 얼굴을 해."),
(V, "(sonríe) Su madre me ha leído como un libro, Daniel.", "(미소 지으며) 어머님이 저를 책 읽듯 읽으셨네요, 다니엘."),
(D_, "Lee a todo el mundo. Cuando yo tenía dieciséis años, me leía las notas del colegio antes de que se las enseñara.", "누구든 다 읽으세요. 제가 열여섯 살 때는 성적표를 보여 드리기도 전에 읽어 내셨어요."),
(None, "Se sientan a la mesa: ropa vieja, arroz blanco, frijoles negros y plátanos maduros fritos. Daniel sirve vino español «en honor a los invitados».", "식탁에 앉는다. 로파 비에하, 흰쌀밥, 검은콩, 그리고 잘 익은 바나나 튀김. 다니엘이 '손님을 기리며' 스페인 와인을 따른다."),
(Y, "Don Vicente, ¿le puedo hacer una pregunta? ¿Cómo se pasa una empresa de padres a hijos sin pelearse?", "비센테 사장님, 질문 하나 드려도 될까요? 회사를 부모에서 자식에게 싸우지 않고 넘기려면 어떻게 해야 하나요?"),
(D_, "Gaby, por favor...", "가비, 제발…"),
(Y, "Es una pregunta de negocios, papá. Él tiene tres generaciones. Nosotros también.", "사업 질문이에요, 아빠. 이분 회사는 3대째예요. 우리도 그렇고요."),
(V, "Le diré la verdad: no se pasa sin pelearse. Mi padre y yo estuvimos dos años sin hablar de la empresa en la mesa.", "솔직히 말씀드리죠. 싸우지 않고는 안 넘어갑니다. 저와 아버지는 2년 동안 식탁에서 회사 얘기를 안 했어요."),
(Y, "¿Dos años?", "2년이요?"),
(V, "Dos años. Antes, el padre decidía y el hijo obedecía. Ahora mi hija me dice que no tres veces por semana. Y tiene razón dos de cada tres.", "2년이요. 예전엔 아버지가 결정하고 아들은 따랐죠. 지금은 제 딸이 일주일에 세 번은 저한테 안 된다고 합니다. 그리고 세 번 중 두 번은 딸 말이 맞아요."),
(D_, "Igual que aquí. Gaby me dice que no a todo y luego me deja ganar en las cosas pequeñas para que no me deprima.", "여기도 똑같아요. 가비는 뭐든 안 된다고 하고, 내가 우울해하지 않게 작은 것만 이기게 해 줘요."),
(Y, "Eso no es verdad. No te dejo ganar en nada.", "그거 사실 아니에요. 아무것도 이기게 안 해 줘요."),
(M, "Los negocios de familia se parecen a los suelos, ¿sabe, don Vicente? Si una pieza está floja, todo suena hueco. Hay que escuchar con los pies.", "가족 사업은 바닥이랑 닮았어요, 비센테 사장님. 한 장이 들뜨면 전체가 텅 빈 소리를 내죠. 발로 들어야 해요."),
(V, "Esa frase me la llevo a Onda, señora. Nuestro jefe de planta la va a colgar en la pared.", "그 말은 온다로 가져가겠습니다, 여사님. 저희 공장장이 벽에 걸어 둘 거예요."),
(M, "Cuélguela con mi nombre. Mercedes Walker, de La Habana. El apellido es de un abuelo inglés de Jamaica que arreglaba ingenios de azúcar.", "제 이름을 붙여서 걸어 주세요. 아바나의 메르세데스 워커. 성은 사탕수수 공장 기계를 고치던 자메이카 출신 영국인 할아버지한테서 왔어요."),
(D_, "Y de Miami, mamá.", "그리고 마이애미의, 엄마."),
(M, "Y de Miami. Pero eso se nota menos.", "그리고 마이애미의. 그건 덜 티가 나지만."),
(L, "Doña Mercedes, ¿sabe que su hijo le ha puesto su nombre a nuestro nuevo diseño?", "메르세데스 여사님, 아드님이 저희 새 디자인에 여사님 이름을 붙인 거 아세요?"),
(M, "¿Mi nombre? ¿A un suelo?", "내 이름을요? 바닥에?"),
(D_, "«Blanco Mercedes». Para las torres de Brickell.", "'블랑코 메르세데스.' 브리켈 타워용이에요."),
(M, "Ay, Daniel. Me van a pisar miles de personas.", "아이고, 다니엘. 수천 명이 나를 밟고 다니겠구나."),
(Y, "Abuela, en esta familia eso es un honor.", "할머니, 우리 집안에선 그게 영광이에요."),
(M, "(se ríe) Entonces, que me pisen con cuidado. Y con los zapatos limpios.", "(웃으며) 그럼 조심해서 밟으라지. 신발도 깨끗하게 하고."),
(V, "Le prometo que será el mejor suelo que hayamos hecho nunca. Como si lo hiciéramos para la ferretería de su suegro.", "저희가 만든 바닥 중 최고가 될 거라고 약속드립니다. 시아버님 철물점에 깔 것처럼 만들게요."),
(M, "Mi suegro se habría reído. Siempre decía que los gallegos de verdad eran los de Galicia y que los demás éramos «gallegos de importación».", "우리 시아버지가 들으셨으면 웃으셨을 거예요. 진짜 갈리시아 사람은 갈리시아 출신뿐이고, 나머지는 '수입산 갈리시아 사람'이라고 늘 말씀하셨거든요."),
(D_, "Por eso los llamo gallegos, don Vicente. Es un cariño.", "그래서 제가 여러분을 갈리시아 사람이라고 부르는 거예요, 사장님. 애정 표현이에요."),
(V, "Ya lo había entendido. En Onda, a los de Madrid les llamamos cosas peores. Pregúntele a Lucas.", "이미 알고 있었어요. 온다에선 마드리드 사람들을 더 심하게 부르거든요. 루카스한테 물어보세요."),
(L, "Al principio era «el de Madrid». Ahora soy Lucas. Tardé tres meses.", "처음엔 '마드리드 사람'이었어요. 지금은 루카스고요. 석 달 걸렸어요."),
(M, "Aquí tardará menos. Ya tiene usted cara de la casa.", "여기선 덜 걸릴 거예요. 벌써 이 집 사람 얼굴이에요."),
(None, "Llega el café, fuerte y dulce, en tacitas de porcelana. Daniel mira el reloj.", "진하고 달콤한 커피가 작은 도자기 잔에 담겨 나온다. 다니엘이 시계를 본다."),
(D_, "Bueno, señores. Un café y a la oficina. A las cinco firmamos. Mamá, tú vienes también.", "자, 여러분. 커피 한 잔 하고 사무실로 가요. 5시에 서명해요. 엄마도 같이 가요."),
(M, "¿Yo? ¿A firmar?", "나도? 서명하러?"),
(D_, "A mirar. Para que don Vicente vea que en esta familia los dueños se miran a los ojos.", "보러요. 이 집안에선 주인들이 서로 눈을 보며 한다는 걸 비센테 사장님이 보시게요."),

("#", "Escena 3 · 17:00 (martes) · Oficina de Daniel, Doral", "장면 3 · 화요일 오후 5시 · 도랄, 다니엘의 사무실"),
(None, "Detrás del escritorio de Daniel cuelga un mapa viejo del Caribe, enmarcado, con manchas de humedad. Sobre la mesa, dos copias del contrato con banderitas amarillas. En la tableta, Amparo, desde Onda, donde son las once de la noche.", "다니엘 책상 뒤에는 습기 얼룩이 진 오래된 카리브해 지도가 액자에 걸려 있다. 테이블 위에는 노란 견출지를 붙인 계약서 두 부. 태블릿 화면에는 밤 11시인 온다의 암파로가 있다."),
(Y, "El contrato está como lo dejamos el día ocho: trece cincuenta FOB, seguro de crédito y la cláusula de aranceles. Ramón pidió dos cambios de redacción por correo. Los he marcado en amarillo.", "계약서는 8일에 정리한 그대로예요. FOB 13.50, 신용보험, 관세 조항. 라몬이 메일로 문구 수정을 두 군데 요청했어요. 노란색으로 표시해 놨어요."),
(V, "Léamelos, por favor. Le prometí a mi hija que lo leería dos veces.", "읽어 주세요. 딸한테 두 번 읽겠다고 약속했거든요."),
(Y, "Cláusula cuarta: «En virtud del presente contrato, Ruiz-Walker actuará como importador y correrá con todos los gastos de aduana y aranceles».", "제4조. '본 계약에 의거하여 루이스워커는 수입자로서 통관비와 관세 일체를 부담한다.'"),
(V, "«En virtud de»... Suena a notario de Castellón.", "'의거하여'라… 카스테욘 공증인 말투 같네."),
(L, "Es lo que pidió Ramón. Que nadie pueda decir después que no estaba claro.", "라몬이 요청한 거예요. 나중에 아무도 불분명했다고 말하지 못하게요."),
(Y, "Y cláusula séptima: «Conforme a lo acordado, el precio se mantendrá fijo durante doce meses y se revisará después anualmente según el precio del gas, con un límite del tres por ciento, salvo que se apruebe un nuevo arancel, en cuyo caso cualquiera de las partes podrá solicitar su revisión en un plazo de treinta días».", "그리고 제7조. '합의한 바에 따라 가격은 12개월간 고정하고, 이후에는 매년 가스 가격에 따라 3% 한도 내에서 재검토한다. 단, 새 관세가 승인되는 경우 어느 당사자든 30일 이내에 가격 재검토를 요청할 수 있다.'"),
(V, "Bien. ¿Y la segunda lectura?", "좋아요. 그럼 두 번째 읽기는요?"),
(Y, "¿Se la vuelvo a leer?", "다시 읽어 드릴까요?"),
(V, "No, hija. La segunda la hago yo. (lee en silencio, siguiendo las líneas con el dedo)", "아니요, 아가씨. 두 번째는 내가 읽어요. (손가락으로 줄을 따라가며 조용히 읽는다)"),
(A, "(en la tableta) Papá, aquí son las once de la noche. Lee rápido, por favor.", "(태블릿 화면에서) 아빠, 여긴 밤 11시예요. 빨리 읽어요, 제발."),
(V, "Amparo, llevo dieciséis años sin firmar un contrato fuera de España. Déjame disfrutarlo.", "암파로, 16년 동안 스페인 밖에서 계약서에 서명을 못 했어. 좀 즐기게 해 줘."),
(A, "Disfrútalo, pero solo dos veces.", "즐기세요. 하지만 두 번만요."),
(D_, "Su hija me cae muy bien, don Vicente. Se parece a la mía.", "따님이 정말 마음에 들어요, 사장님. 우리 딸이랑 닮았어요."),
(V, "Eso es lo que me preocupa. (deja el contrato) Leído dos veces. ¿Dónde firmo?", "그게 걱정이에요. (계약서를 내려놓으며) 두 번 읽었습니다. 어디에 서명하면 되죠?"),
(Y, "Aquí, aquí y en la última página, con la fecha.", "여기, 여기, 그리고 마지막 장에 날짜와 함께요."),
(None, "Vicente saca una pluma estilográfica del bolsillo de la americana. Daniel saca otra. Firman a la vez, mirándose por encima de los papeles. Doña Mercedes aplaude despacio.", "비센테가 재킷 주머니에서 만년필을 꺼낸다. 다니엘도 하나 꺼낸다. 서류 너머로 서로를 바라보며 동시에 서명한다. 메르세데스 여사가 천천히 박수를 친다."),
(D_, "Firmado. En Doral, a veintidós de septiembre. Mirándonos a los ojos.", "서명 완료. 도랄에서, 9월 22일. 서로 눈을 보면서."),
(V, "Mirándonos a los ojos. Gracias, Daniel. Es como si volviera a tener cuarenta años.", "서로 눈을 보면서. 고마워요, 다니엘. 다시 마흔 살이 된 것 같네요."),
(M, "A los cuarenta se firma con prisa. A los sesenta y cuatro se firma con memoria. Es mejor.", "마흔에는 서둘러서 서명하죠. 예순넷에는 기억을 담아 서명하고요. 그게 더 나아요."),
(None, "Suena el móvil de Gaby. En la pantalla: Atlanta.", "가비의 휴대폰이 울린다. 화면에는 '애틀랜타'."),
(Y, "Es Kevin. Lo pongo en altavoz.", "케빈이에요. 스피커로 돌릴게요."),
(K, "¡Gente! ¿Me oyen? Tengo noticias de mi jefe. ¿Están sentados?", "여러분! 들려요? 상사 소식이 있어요. 앉아 있어요?"),
(D_, "Estamos firmando, Kevin. Más sentados no podemos estar.", "서명하고 있어, 케빈. 이보다 더 앉아 있을 순 없어."),
(K, "Perfecto. Mi jefe aprueba el piloto. Marca Albalat, sin marca propia y con un tope de chargebacks del dos por ciento. Pero empezamos con veinte tiendas, no con cuarenta. Florida y Georgia.", "완벽하네요. 상사가 시범 판매를 승인했어요. 알발라트 브랜드로, 자체 브랜드 없이, 차지백 상한 2%로요. 하지만 40곳이 아니라 20곳으로 시작해요. 플로리다랑 조지아."),
(L, "¿Veinte? ¿Y la revisión?", "20곳이요? 재검토는요?"),
(K, "A los seis meses. Si los números salen bien, pasamos a cuarenta. Si salen muy bien, hablamos del país entero.", "6개월 차에요. 숫자가 좋으면 40곳으로 늘려요. 아주 좋으면 전국 얘기를 하고요."),
(A, "¿Y los expositores y la formación de los vendedores?", "진열대랑 판매 직원 교육은요?"),
(K, "Los quiere en las veinte tiendas antes del cambio de surtido de febrero, con el stock en nuestros centros de distribución el quince de enero. Y Denise quiere auditar la fábrica de Onda en noviembre. Mi jefe dijo, literalmente: «Quiero ver esos hornos en Georgia».", "2월 진열 개편 전에 20개 매장 모두에 갖춰 놓고, 재고는 1월 15일까지 우리 물류센터에 넣어 달래요. 그리고 드니스가 11월에 온다 공장을 감사하고 싶대요. 상사가 그대로 이렇게 말했어요. '그 가마들을 조지아에서 보고 싶다.'"),
(Y, "¿Y el pago a setenta y cinco días?", "75일 지급은요?"),
(K, "Setenta y cinco. Gaby, no me mires así por teléfono, que lo noto.", "75일. 가비, 전화로 그렇게 째려보지 마요. 다 느껴져요."),
(L, "Kevin, en nombre de Cerámicas Albalat... aceptamos. Con mucho gusto.", "케빈, 세라미카스 알발라트를 대표해서… 받아들입니다. 기꺼이요."),
(K, "¡Brutal! Mañana les mando el contrato de vendor modificado. ¡Bienvenidos a BuildMart!", "대박! 내일 수정된 공급업체 계약서 보낼게요. 빌드마트에 오신 걸 환영해요!"),
(None, "Kevin cuelga. Daniel saca de un armario una botella de ron añejo y unos vasitos.", "케빈이 전화를 끊는다. 다니엘이 장에서 숙성 럼 한 병과 작은 잔들을 꺼낸다."),
(D_, "Esto hay que celebrarlo. Mamá, el brindis es tuyo.", "이건 축하해야지. 엄마, 건배사는 엄마가 해요."),
(M, "(levanta el vaso) Brindo por las maletas. Por la de mi suegro, que salió de Llanes; por la mía, que salió de La Habana; y por la de don Vicente, que ha vuelto a salir de Onda.", "(잔을 들며) 가방들을 위해 건배해요. 야네스를 떠난 우리 시아버지의 가방, 아바나를 떠난 내 가방, 그리고 다시 온다를 떠나온 비센테 사장님의 가방을 위해."),
(V, "Y yo brindo por las baldosas, que viajan mejor que nosotros y nunca se quejan del calor.", "그리고 저는 타일을 위해 건배합니다. 우리보다 여행도 잘하고, 더위에 불평도 안 하니까요."),
(None, "Todos beben. Lucas, en un rincón, saca del bolsillo una chincheta amarilla y la mira.", "모두 잔을 비운다. 루카스는 구석에서 주머니 속 노란 압정을 꺼내 바라본다."),
(Y, "¿Qué tienes ahí, Lucas?", "거기 뭐 들고 있어요, 루카스?"),
(L, "Una chincheta. En nuestra oficina de Onda hay un mapa con una chincheta roja en Monterrey. Llevo esta en el bolsillo desde julio. Esperaba a que firmáramos.", "압정이요. 온다 사무실에 몬테레이에 빨간 압정이 꽂힌 지도가 있어요. 이건 7월부터 주머니에 넣고 다녔어요. 서명할 때까지 기다리고 있었죠."),
(M, "Ese mapa colgaba en la ferretería de mi suegro. Raúl y yo lo trajimos en la maleta; es lo único que trajimos además de la ropa. Póngala ahí, en Miami. Que el mapa de Onda espere.", "저 지도는 시아버지 철물점에 걸려 있던 거예요. 라울과 내가 가방에 넣어 왔죠. 옷 말고 가져온 건 그것뿐이에요. 저기, 마이애미에 꽂아요. 온다 지도는 좀 기다리라고 해요."),
(L, "(clava la chincheta amarilla en Miami, junto al borde del marco) Miami.", "(액자 가장자리 가까이, 마이애미에 노란 압정을 꽂으며) 마이애미."),
(V, "(mirando el mapa, en voz baja) Llanes, La Habana, Onda, Miami... Mi padre no se lo creería.", "(지도를 바라보며 낮은 목소리로) 야네스, 아바나, 온다, 마이애미… 우리 아버지가 보셨으면 믿지 못하셨을 거야."),
(None, "El miércoles por la mañana, Vicente y Lucas despegan rumbo a Valencia. En la maleta antigua, envuelta en un pañuelo, va una servilleta con una frase escrita a mano: «Hay que escuchar con los pies. — Mercedes».", "수요일 아침, 비센테와 루카스는 발렌시아로 이륙한다. 낡은 여행 가방 속에는 손수건에 싼 냅킨 한 장이 들어 있다. 거기엔 손글씨로 이렇게 적혀 있다. '발로 들어야 한다. — 메르세데스'"),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "2009년 과달라하라 이후 처음으로 비센테가 일 때문에 대서양을 건넌다. 공항에서 호텔로 가는 차 안에서 그는 루카스에게 그때 무엇을 잘못했는지 털어놓는다. 다음 날, 다니엘의 집에서 여든다섯 살의 메르세데스 여사와 점심을 먹는다. 아스투리아스에서 쿠바로, 쿠바에서 마이애미로 이어진 가족사, 그리고 카스테욘의 타일 이야기. 오후에는 서로 눈을 보며 서명하고, 그 순간 애틀랜타에서 전화가 온다. 루카스는 7월부터 주머니에 넣고 다닌 노란 압정을 마침내 꽂는다.",
 "듣기 질문 ① 암파로가 비센테에게 약속하게 한 세 가지는? 비센테는 2009년과 지금이 어떻게 다르다고 말하는가?",
 "듣기 질문 ② 메르세데스 여사의 가족은 어디에서 어디로 옮겨 왔는가? 그녀가 가족 사업을 무엇에 비유하는가?",
 "듣기 질문 ③ 빌드마트가 승인한 시범 판매 조건은? 루카스는 노란 압정을 어디에, 왜 그곳에 꽂는가?",
]),
]

